26	/**
27	 * Each person's claimed, due-total and overdue-total on a sheet, and the sheet's totals, as the screen
28	 * shows them.
29	 * A change takes the figures before it, then records after its own audit lines a ROLLUP line for each
30	 * person whose figures moved (a person new to the sheet counting as moved), in the order they were
31	 * added, and a TOTALS line when the sheet's totals moved.
32	 */
33	@Service
34	public class Rollup {
35	
36	    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);
37	
38	    /** A person's figures; a null due-total is n/a. */
39	    public record Figures(String name, BigDecimal claimed, BigDecimal dueTotal, BigDecimal overdueTotal) {
40	    }
41	
42	    /** Everyone's figures by person id, in the order they were added, and the sheet's totals. */
43	    public record Snapshot(Map<Long, Figures> people, BigDecimal claimedTotal, BigDecimal dueTotal,
44	            BigDecimal overdueTotal) {
45	    }
46	
47	    private final PersonRepository people;
48	    private final ClaimRepository claims;
49	    private final RateRepository rates;
50	    private final SheetRepository sheets;
51	    private final Audit audit;
52	
53	    public Rollup(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
54	            Audit audit) {
55	        this.people = people;
56	        this.claims = claims;
57	        this.rates = rates;
58	        this.sheets = sheets;
59	        this.audit = audit;
60	    }
61	
62	    /** The sheet's figures now. */
63	    public Snapshot take(String sheetId) {
64	        Optional<Sheet> sheet = sheets.findById(sheetId);
65	        LocalDate today = sheet.map(Sheet::getToday).orElse(null);
66	        List<Rate> sheetRates = rates.findBySheetIdOrderByGradeAsc(sheetId);
67	        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
68	        Map<Long, Figures> figures = new LinkedHashMap<>();
69	        BigDecimal claimedTotal = ZERO;
70	        List<BigDecimal> dues = new ArrayList<>();
71	        List<BigDecimal> overdues = new ArrayList<>();
72	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
73	            BigDecimal claimed = ZERO;
74	            BigDecimal due = ZERO;
75	            BigDecimal overdue = ZERO;
76	            boolean keptFigure = false;
77	            for (Claim claim : sheetClaims) {
78	                if (!claim.getPersonId().equals(person.getId()) || !countsLive(claim, person, today)) {
79	                    continue;
80	                }
81	                claimed = claimed.add(claim.getAmount());
82	                BigDecimal kept = claim.getSettledDue() != null ? claim.getSettledDue()
83	                        : claim.isBound() ? claim.getStatedDue() : null;
84	                BigDecimal figure = null;
85	                if (kept != null) {
86	                    keptFigure = true;
87	                    figure = charged(sheet, claim, kept);
88	                } else if (!claim.isBound()) {
89	                    // a claim priced at the grade in force on its date keeps a figure too
90	                    BigDecimal live = inForce(sheetRates, person.gradeOn(claim.getDate()), claim.getDate())
91	                            .map(rate -> rated(sheet, claim, sheetClaims, rate))
92	                            .orElse(null);
93	                    if (live != null) {
94	                        keptFigure = true;
95	                        figure = charged(sheet, claim, live);
96	                    }
97	                }
98	                if (figure != null) {
99	                    due = due.add(figure);
100	                    if (overdue(claim, today)) {
101	                        overdue = overdue.add(figure);
102	                    }
103	                }
104	            }
105	            boolean rated = today != null && inForce(sheetRates, person.gradeOn(today), today).isPresent();
106	            BigDecimal personDue = rated || keptFigure ? capped(sheet, due) : null;
107	            figures.put(person.getId(), new Figures(person.getName(), claimed, personDue, overdue));
108	            claimedTotal = claimedTotal.add(claimed);
109	            overdues.add(overdue);
110	            if (personDue != null) {
111	                dues.add(personDue);
112	            }
113	        }
114	        return new Snapshot(figures, claimedTotal, trimmed(dues), trimmed(overdues));
115	    }
116	
117	    /** People's figures added up, leaving out the single highest and the single lowest when there are three
118	     *  or more. */
119	    static BigDecimal trimmed(List<BigDecimal> figures) {
120	        BigDecimal sum = figures.stream().reduce(ZERO, BigDecimal::add);
121	        if (figures.size() < 3) {
122	            return sum;
123	        }
124	        BigDecimal max = figures.stream().max(BigDecimal::compareTo).orElseThrow();
125	        BigDecimal min = figures.stream().min(BigDecimal::compareTo).orElseThrow();
126	        return sum.subtract(max).subtract(min);
127	    }
128	
129	    /** Each person's due-total of their claims dated from one date to another, both inclusive, by person
130	     *  id, every person on the sheet in the order they were added, as the screen shows a person's for a
131	     *  period: a claim counts by the status it had at the end of the last day, as its status log records
132	     *  it (one added after then does not), unless a hold or a deferral leaves it out now; each counts its
133	     *  due as shown now: its settled due, else the figure its statement bound, else its live due, an
134	     *  overdue claim's late charge on top, at least the floor (a claim with no figure adds nothing). */
135	    public Map<Long, BigDecimal> dueBetweenByPerson(String sheetId, LocalDate from, LocalDate to) {
136	        Optional<Sheet> sheet = sheets.findById(sheetId);
137	        LocalDate today = sheet.map(Sheet::getToday).orElse(null);
138	        List<Rate> sheetRates = rates.findBySheetIdOrderByGradeAsc(sheetId);
139	        Map<Long, Person> byId = new LinkedHashMap<>();
140	        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
141	        people.findBySheetIdOrderByIdAsc(sheetId).forEach(p -> {
142	            byId.put(p.getId(), p);
143	            totals.put(p.getId(), ZERO);
144	        });
145	        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
146	        for (Claim claim : sheetClaims) {
147	            Person person = byId.get(claim.getPersonId());
148	            if (person == null || claim.getDate().isBefore(from) || claim.getDate().isAfter(to)
149	                    || !countsAt(claim, to) || heldOut(claim, person, today) || claim.deferredOn(today)) {
150	                continue;
151	            }
152	            BigDecimal due;
153	            if (claim.getSettledDue() != null) {
154	                due = claim.getSettledDue();
155	            } else if (claim.isBound()) {
156	                due = claim.getStatedDue();
157	            } else {
158	                due = inForce(sheetRates, person.gradeOn(claim.getDate()), claim.getDate())
159	                        .map(rate -> rated(sheet, claim, sheetClaims, rate))
160	                        .orElse(null);
161	            }
162	            if (due != null) {
163	                totals.merge(person.getId(), charged(sheet, claim, due), BigDecimal::add);
164	            }
165	        }
166	        return totals;
167	    }
168	
169	    /** Record, once the change commits, a SNAPSHOT line of each person's due-total in a snapshot, in the
170	     *  order they were added. */
171	    public void recordSnapshot(String sheetId, String user, Snapshot snapshot) {
172	        String prefix = " sheet=" + sheetId + " by=" + user;
173	        snapshot.people().values().forEach(figures -> audit.recordOnCommit("SNAPSHOT" + prefix
174	                + " name=" + figures.name() + " due-total=" + show(figures.dueTotal())));
175	    }
176	
177	    /** Record, once the change commits, the lines for every figure that moved since {@code before}. */
178	    public void recordChanges(String sheetId, String user, Snapshot before) {
179	        Snapshot after = take(sheetId);
180	        String prefix = " sheet=" + sheetId + " by=" + user;
181	        after.people().forEach((id, now) -> {
182	            Figures was = before.people().get(id);
183	            if (was == null || was.claimed().compareTo(now.claimed()) != 0
184	                    || !sameDue(was.dueTotal(), now.dueTotal())
185	                    || was.overdueTotal().compareTo(now.overdueTotal()) != 0) {
186	                audit.recordOnCommit("ROLLUP" + prefix + " person=" + now.name()
187	                        + " claimed=" + now.claimed().toPlainString() + " due-total=" + show(now.dueTotal())
188	                        + " overdue-total=" + now.overdueTotal().toPlainString());
189	            }
190	        });
191	        if (before.claimedTotal().compareTo(after.claimedTotal()) != 0
192	                || before.dueTotal().compareTo(after.dueTotal()) != 0
193	                || before.overdueTotal().compareTo(after.overdueTotal()) != 0) {
194	            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + after.claimedTotal().toPlainString()
195	                    + " due-total=" + after.dueTotal().toPlainString()
196	                    + " overdue-total=" + after.overdueTotal().toPlainString());
197	        }
198	    }
199	
200	    /** Whether a claim counts in the live totals: its status counts, it is not left out by a hold, and it
201	     *  is not deferred past the sheet's today. */
202	    private static boolean countsLive(Claim claim, Person person, LocalDate today) {
203	        return claim.getStatus().counts() && !heldOut(claim, person, today) && !claim.deferredOn(today);
204	    }
205	
206	    /** Whether a claim counted by the status it had at the end of a day, as its status log records it:
207	     *  its latest line dated on or before it; not when it was added after it. A claim with no log counts
208	     *  by its status now. */
209	    private static boolean countsAt(Claim claim, LocalDate day) {
210	        List<StatusChange> log = claim.getStatusLog();
211	        if (log.isEmpty()) {
212	            return claim.getStatus().counts();
213	        }
214	        ClaimStatus status = null;
215	        for (StatusChange change : log) {
216	            if (!change.getOn().isAfter(day)) {
217	                status = change.getStatus();
218	            }
219	        }
220	        return status != null && status.counts();
221	    }
222	
223	    /** Whether a claim is overdue: OPEN or PENDING, not deferred, with its due-by before the sheet's today. */
224	    private static boolean overdue(Claim claim, LocalDate today) {
225	        return claim.getStatus().isOpen() && !claim.deferredOn(today) && today != null && claim.getDueBy() != null
226	                && claim.getDueBy().isBefore(today);
227	    }
228	
229	    /** Whether a hold or a retirement leaves a claim out of the live totals: it is OPEN or PENDING, bound by
230	     *  no statement, and dated within one of its person's holds or its person's retirement date is reached on
231	     *  the sheet's today. */
232	    public static boolean heldOut(Claim claim, Person person, LocalDate today) {
233	        return person != null && claim.getStatus().isOpen() && !claim.isBound()
234	                && (person.heldOn(claim.getDate()) || person.retiredBy(today));
235	    }
236	
237	    /** A claim's amount at a rate, divided by 100, rounded to cents as the claim's rounding date rounds on
238	     *  the sheet (half to even with no sheet). */
239	    public static BigDecimal rated(Optional<Sheet> sheet, Claim claim, List<Claim> sheetClaims, Rate rate) {
240	        LocalDate on = roundingDate(claim, sheetClaims);
241	        return claim.getAmount().multiply(rate.getRate()).movePointLeft(2)
242	                .setScale(2, sheet.map(s -> s.rounding(on)).orElse(RoundingMode.HALF_EVEN));
243	    }
244	
245	    /** The date a claim's figures round by: its own, or for a correction the date of the claim it
246	     *  corrects (the claim of the same person with that number), its own when that is not found. */
247	    public static LocalDate roundingDate(Claim claim, List<Claim> sheetClaims) {
248	        if (!claim.isCorrection()) {
249	            return claim.getDate();
250	        }
251	        return sheetClaims.stream()
252	                .filter(c -> c.getPersonId().equals(claim.getPersonId()) && claim.getCorrects().equals(c.getNumber()))
253	                .findFirst().map(Claim::getDate).orElse(claim.getDate());
254	    }
255	
256	    /** A claim's due from its figure (its rate figure, or the one its statement bound): its late charge on
257	     *  top while it is OPEN or PENDING (only those go overdue), then at least the sheet's floor in force on its
258	     *  date. A settled claim's due is frozen (it already holds the charge and floor fixed when it was
259	     *  settled); a correction has neither late charge nor floor. */
260	    public static BigDecimal charged(Optional<Sheet> sheet, Claim claim, BigDecimal figure) {
261	        if (claim.getSettledDue() != null || claim.isCorrection()) {
262	            return figure;
263	        }
264	        return sheet.map(s -> s.floored(claim.getStatus().isOpen()
265	                ? figure.add(s.lateCharge(figure, claim.getDueBy(), claim.getDate())) : figure, claim.getDate()))
266	                .orElse(figure);
267	    }
268	
269	    /** A person's due-total at most the sheet's cap. */
270	    private static BigDecimal capped(Optional<Sheet> sheet, BigDecimal dueTotal) {
271	        return sheet.map(s -> s.capped(dueTotal)).orElse(dueTotal);
272	    }
273	
274	    private static boolean sameDue(BigDecimal a, BigDecimal b) {
275	        return a == null || b == null ? Objects.equals(a, b) : a.compareTo(b) == 0;
276	    }
277	
278	    private static String show(BigDecimal due) {
279	        return due == null ? "n/a" : due.toPlainString();
280	    }
281	
282	    /** The grade's rate in force on a date: the latest from-date on or before it, none first; none
283	     *  when the date is after that rate's to-date. */
284	    public static Optional<Rate> inForce(List<Rate> sheetRates, String grade, LocalDate date) {
285	        return sheetRates.stream()
286	                .filter(r -> r.getGrade().equals(grade))
287	                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
288	                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
289	                .filter(r -> r.coversThrough(date));
290	    }
291	}
